 "content": "def transform(grid):
    """Complete broken horizontal bars and extend vertical rays upward."""
    h, w = len(grid), len(grid[0]) if grid else 0
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]

    # Horizontal bars contain a one-cell gap between matching colored parts.
    gaps = []
    for r in range(h):
        for c in range(1, w - 1):
            color = src[r][c - 1]
            if color and src[r][c] == 0 and src[r][c + 1] == color:
                out[r][c] = color
                gaps.append((r, c, color))

    # Every broken-bar gap projects its color upward until it meets an object.
    for r, c, color in sorted(gaps, reverse=True):
        rr = r - 1
        while rr >= 0 and out[rr][c] == 0:
            out[rr][c] = color
            rr -= 1

    # Vertical clues (including isolated markers) also project upward. A
    # horizontal bar cell is not a clue unless it belongs to a vertical run.
    for c in range(w):
        r = 0
        while r < h:
            color = src[r][c]
            if not color:
                r += 1
                continue
            end = r
            while end + 1 < h and src[end + 1][c] == color:
                end += 1
            if end > r or not any(src[r][cc] == color for cc in range(max(0, c - 1), min(w, c + 2)) if cc != c):
                rr = r - 1
                while rr >= 0 and out[rr][c] == 0:
                    out[rr][c] = color
                    rr -= 1
            r = end + 1
    return out


if __name__ == '__main__':
    import sys, json
    print(json.dumps(transform(json.load(sys.stdin))))
